# Analyze the structure - identify sections separated by full 9-rows
print("Horizontal separator rows (all 9s):")
for i in range(grid.shape[0]):
    if np.all(grid[i] == 9):
        print(f"  Row {i}")

print("\nSection analysis:")
sections = []
current_section = []
for i in range(grid.shape[0]):
    if np.all(grid[i] == 9):
        if current_section:
            sections.append(current_section)
            current_section = []
        else:
            # First separator row
            sections.append([])
    else:
        current_section.append((i, grid[i].copy()))

if current_section:
    sections.append(current_section)

for idx, section in enumerate(sections):
    print(f"\nSection {idx}:")
    for row_idx, (grid_row_idx, data) in enumerate(section):
        if isinstance(data, list):
            print(f"  Grid row {grid_row_idx}: length={len(data)}, sum={sum(data)}")
